import * as THREE from 'three';

const $=s=>document.querySelector(s);
const ui={title:$('#title-screen'),hud:$('#hud'),prompt:$('#start-prompt'),pause:$('#pause-screen'),finish:$('#finish-screen'),timer:$('#timer'),speed:$('#speed'),bars:$('#speed-bars'),progress:$('#progress-fill'),pct:$('#progress-pct'),state:$('#run-state'),best:$('#best-time'),menuBest:$('#menu-best'),split:$('#split-pop'),mobile:$('#mobile-controls')};
const BEST_KEY='roofline-best-v1';
let best=Number(localStorage.getItem(BEST_KEY))||0;
function timeText(t){if(!t)return '—:——.——';const m=Math.floor(t/60),s=Math.floor(t%60),c=Math.floor((t%1)*100);return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}.${String(c).padStart(2,'0')}`}
ui.best.textContent=ui.menuBest.textContent=timeText(best);
for(let i=0;i<22;i++){const b=document.createElement('i');ui.bars.append(b)}
const speedBars=[...ui.bars.children];
const scene=new THREE.Scene();scene.background=new THREE.Color(0x899aa4);scene.fog=new THREE.FogExp2(0x899aa4,.0065);
const camera=new THREE.PerspectiveCamera(76,innerWidth/innerHeight,.08,600);camera.rotation.order='YXZ';
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;renderer.outputColorSpace=THREE.SRGBColorSpace;$('#game').appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xc9d9e3,0x29323a,2.1));
const sun=new THREE.DirectionalLight(0xffdfbd,3.8);sun.position.set(-32,48,18);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-65;sun.shadow.camera.right=65;sun.shadow.camera.top=40;sun.shadow.camera.bottom=-210;sun.shadow.camera.near=1;sun.shadow.camera.far=270;sun.shadow.bias=-.00015;scene.add(sun);
const fill=new THREE.DirectionalLight(0x8db6d2,1.3);fill.position.set(45,22,-100);scene.add(fill);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
function noiseTexture(base='#77736b',seed=4){const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d');x.fillStyle=base;x.fillRect(0,0,256,256);let v=seed;for(let i=0;i<12000;i++){v=(v*1664525+1013904223)>>>0;const a=(v&255)/255*.18;x.fillStyle=(v&1)?`rgba(230,225,209,${a})`:`rgba(20,25,29,${a})`;const px=v%256,py=(v>>>8)%256;x.fillRect(px,py,1+(v%3),1+(v%2))}const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.colorSpace=THREE.SRGBColorSpace;return t}
const concreteTex=noiseTexture('#77756e',42);concreteTex.repeat.set(3,8);
const concrete= new THREE.MeshStandardMaterial({map:concreteTex,color:0xd0c8b7,roughness:.92});
const darkConcrete=new THREE.MeshStandardMaterial({map:noiseTexture('#343b3c',24),color:0xb4b6af,roughness:.85});
const metal=mat(0x40494b,.38,.72),railMat=mat(0x687476,.34,.8),yellow=mat(0xe4a45f,.65,.1),glow=new THREE.MeshBasicMaterial({color:0xf38b52});
const floorMat=mat(0x252d31,.9);
const floor=new THREE.Mesh(new THREE.PlaneGeometry(900,900),floorMat);floor.rotation.x=-Math.PI/2;floor.position.set(0,-29,-85);floor.receiveShadow=true;scene.add(floor);
// Procedural city blocks, antennae, windows and distant silhouettes.
let seed=70;const rand=()=>((seed=(seed*1664525+1013904223)>>>0)/4294967296);
const buildings=[];
for(let side of [-1,1])for(let i=0;i<23;i++){const z=13-i*9.4-rand()*5,w=8+rand()*15,h=20+rand()*54,d=9+rand()*18,x=side*(15+rand()*20);const g=new THREE.Group();const b=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),[mat(0x424c50,.85),mat(0x596165,.8),mat(0x333e43,.85)][i%3]);b.position.y=h/2-5;b.castShadow=true;b.receiveShadow=true;g.add(b);const roof=new THREE.Mesh(new THREE.BoxGeometry(w+1,.45,d+1),mat(0x707777,.65,.2));roof.position.y=h-4.8;g.add(roof);
 const winMat=new THREE.MeshBasicMaterial({color:i%4===0?0xc68a62:0x68828c,transparent:true,opacity:.27});for(let row=0;row<Math.min(11,Math.floor(h/4));row++)for(let col=0;col<Math.floor(w/2.5);col++){if(rand()<.24)continue;const win=new THREE.Mesh(new THREE.PlaneGeometry(.72,1.45),winMat);win.position.set(-w/2+1.2+col*2.35,-h/2+3.5+row*3.1,d/2+.011);g.add(win)}
 if(i%3===0){const pipe=new THREE.Mesh(new THREE.CylinderGeometry(.13,.13,5,8),metal);pipe.position.set(w*.27,h-2,-d*.22);g.add(pipe);const tip=new THREE.Mesh(new THREE.SphereGeometry(.22,8,6),yellow);tip.position.set(w*.27,h+.55,-d*.22);g.add(tip)}g.position.set(x,0,z);scene.add(g);buildings.push(g)}
// Distant tower silhouettes soften the horizon.
for(let i=0;i<32;i++){const w=9+rand()*20,h=30+rand()*75;const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,12+rand()*18),mat(0x606d71,.92));m.position.set((rand()-.5)*230,h/2-7,-65-rand()*110);scene.add(m)}
// Rooftop course: broad concrete pads and deliberate, jumpable breaks.
const pads=[];let zStart=9;const courseEnd=-146;const specs=[[-17,0],[-34,.25],[-52,.5],[-70,.9],[-88,.55],[-106,1.05],[-124,.65],[-146,1.15]];let prevEnd=zStart;
function addBox(parent,geo,material,x,y,z,shadow=true){const o=new THREE.Mesh(geo,material);o.position.set(x,y,z);o.castShadow=shadow;o.receiveShadow=true;parent.add(o);return o}
for(let i=0;i<specs.length;i++){const [end,height]=specs[i],start=i===0?zStart:prevEnd+1.15;const length=start-end;const group=new THREE.Group();const slab=addBox(group,new THREE.BoxGeometry(10,length,.9),concrete,0,height-.45,(start+end)/2);slab.rotation.x=Math.PI/2; // box dims are width,height,depth; rotate to make depth along Z
 // Rotation above maps length axis into world z, thickness into y.
 const top=height;const stripMat=mat(0xc7b99f,.8);for(const sx of [-4.65,4.65]){const edge=addBox(group,new THREE.BoxGeometry(.11,length-.2,.035),yellow,sx,top-.08,(start+end)/2,false);edge.rotation.x=Math.PI/2}
 // Center lane markings, spaced like a real service deck.
 for(let zz=end+3;zz<start-1;zz+=7){const dash=addBox(group,new THREE.BoxGeometry(.09,1.05,.025),stripMat,0,top-.065,zz,false);dash.rotation.x=Math.PI/2}
 // Drain channels at the pad edges.
 for(const sx of [-4.25,4.25]){const drain=addBox(group,new THREE.BoxGeometry(.18,length-.7,.04),metal,sx,top-.07,(start+end)/2,false);drain.rotation.x=Math.PI/2}
 group.position.y=0;scene.add(group);pads.push({start,end,top});prevEnd=end;
 // Side-mounted amber course lamps at each landing.
 const markerZ=end+1.2;for(const sx of [-5.4,5.4]){const post=addBox(scene,new THREE.BoxGeometry(.11,.8,.11),metal,sx,height+.4,markerZ,false);const lamp=addBox(scene,new THREE.BoxGeometry(.18,.16,.12),glow,sx,height+.78,markerZ,false)}
 // rooftop equipment away from the runnable center strip
 if(i%2===1){const box=addBox(group,new THREE.BoxGeometry(1.6,.65,1.2),darkConcrete,3.1,top+.32,end+5);const vent=addBox(group,new THREE.BoxGeometry(1.25,.12,.95),railMat,3.1,top+.71,end+5,false)}
}
// Rooftop parapets and cross-braced safety rails on outer edges.
for(const pad of pads){for(const side of [-1,1]){const x=side*5.15,mid=(pad.start+pad.end)/2,len=pad.start-pad.end;
 const curb=addBox(scene,new THREE.BoxGeometry(.32,.43,len),darkConcrete,x,pad.top+.18,mid);const rail=addBox(scene,new THREE.BoxGeometry(.08,.07,len),railMat,x,pad.top+1.18,mid,false);
 for(let zz=pad.end+.5;zz<pad.start;zz+=2.9)addBox(scene,new THREE.BoxGeometry(.07,1.13,.07),railMat,x,pad.top+.62,zz,false);
 }}
// Finish gantry and glowing route beacon.
const finishZ=courseEnd-2;for(const x of [-4.8,4.8]){addBox(scene,new THREE.BoxGeometry(.22,5,.24),metal,x,3,finishZ,false);addBox(scene,new THREE.BoxGeometry(.3,.34,.3),glow,x,5.55,finishZ,false)}addBox(scene,new THREE.BoxGeometry(9.8,.22,.25),railMat,0,5.52,finishZ,false);const gateLight=addBox(scene,new THREE.BoxGeometry(7.5,.1,.16),glow,0,5.33,finishZ,false);
// Sun glow disc, just above the hazy skyline.
const sunDisc=new THREE.Mesh(new THREE.CircleGeometry(7,48),new THREE.MeshBasicMaterial({color:0xf5c49d,transparent:true,opacity:.72,depthWrite:false}));sunDisc.position.set(-73,50,-215);sunDisc.lookAt(0,15,-110);scene.add(sunDisc);
const player={x:0,y:0,z:4,vx:0,vy:0,vz:0,yaw:0,pitch:0,grounded:true};const eye=1.68;
let mode='menu',running=false,startedAt=0,elapsed=0,last=performance.now(),jumps=0,airTime=0,airStart=0,topSpeed=0,prevProgress=0,lookActive=false;
const keys={};let jumpHeld=false,mobileMove={x:0,y:0};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function resetPlayer(){Object.assign(player,{x:0,y:0,z:4,vx:0,vy:0,vz:0,yaw:0,pitch:0,grounded:true});camera.position.set(0,eye,4);camera.rotation.set(0,0,0);elapsed=0;jumps=0;airTime=0;topSpeed=0;prevProgress=0;ui.progress.style.width='0%';ui.pct.textContent='0%';ui.timer.textContent='00:00.00';ui.speed.textContent='0';ui.state.textContent='FIND YOUR LINE';}
function show(el){el.classList.add('visible')}function hide(el){el.classList.remove('visible')}
function setMode(m){mode=m;ui.hud.classList.toggle('hidden',m==='menu'||m==='finish');ui.prompt.classList.toggle('hidden',m!=='ready');ui.mobile.classList.toggle('hidden',!(m==='ready'||m==='run'));if(m==='menu')show(ui.title);else hide(ui.title);if(m==='pause')show(ui.pause);else hide(ui.pause);if(m==='finish')show(ui.finish);else hide(ui.finish)}
function begin(){resetPlayer();setMode('ready');renderer.domElement.requestPointerLock?.();}
function startRun(){if(mode!=='ready')return;mode='run';hide(ui.prompt);startedAt=performance.now();ui.state.textContent='KEEP THE MOMENTUM';}
function resume(){if(mode==='pause'){setMode('run');renderer.domElement.requestPointerLock?.();last=performance.now()}}
function pause(){if(mode==='run'||mode==='ready'){setMode('pause');document.exitPointerLock?.()}}
function complete(){elapsed=(performance.now()-startedAt)/1000;setMode('finish');document.exitPointerLock?.();$('#final-time').textContent=timeText(elapsed);$('#final-speed').innerHTML=`${Math.round(topSpeed*3.6)} <small>KM/H</small>`;$('#final-jumps').textContent=jumps;$('#final-air').innerHTML=`${airTime.toFixed(1)}<small> SEC</small>`;const record=!best||elapsed<best;if(record){best=elapsed;localStorage.setItem(BEST_KEY,best);ui.best.textContent=ui.menuBest.textContent=timeText(best)}$('#new-best').style.visibility=record?'visible':'hidden';}
$('#start-btn').addEventListener('click',begin);$('#resume-btn').addEventListener('click',resume);$('#restart-btn').addEventListener('click',begin);$('#again-btn').addEventListener('click',begin);
renderer.domElement.addEventListener('click',()=>{if(mode==='ready'){renderer.domElement.requestPointerLock?.();startRun()}else if(mode==='run'&&document.pointerLockElement!==renderer.domElement)renderer.domElement.requestPointerLock?.()});
document.addEventListener('pointerlockchange',()=>{lookActive=document.pointerLockElement===renderer.domElement;if(!lookActive&&mode==='run')pause()});
document.addEventListener('mousemove',e=>{if(!lookActive||mode!=='run')return;player.yaw-=e.movementX*.0022;player.pitch=clamp(player.pitch-e.movementY*.0018,-1.25,1.25)});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space'){jumpHeld=true;if(mode==='ready')startRun()}if(e.code==='Escape'&&mode==='run')pause();if(e.code==='KeyR'&&(mode==='run'||mode==='pause'))begin();if(mode==='ready'&&['KeyW','KeyA','KeyS','KeyD'].includes(e.code))startRun()});
document.addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='Space')jumpHeld=false});
const stick=$('#mobile-stick'),stickDot=stick.querySelector('span');let stickPointer=null;
stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);if(mode==='ready')startRun();moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)moveStick(e)});function moveStick(e){const r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),scale=Math.min(1,len/37);mobileMove.x=dx/(len||1)*scale;mobileMove.y=dy/(len||1)*scale;stickDot.style.transform=`translate(${mobileMove.x*34}px,${mobileMove.y*34}px)`}stick.addEventListener('pointerup',()=>{stickPointer=null;mobileMove={x:0,y:0};stickDot.style.transform=''});let jumpPointer=false;$('#mobile-jump').addEventListener('pointerdown',e=>{e.preventDefault();jumpPointer=true;jumpHeld=true;if(mode==='ready')startRun()});$('#mobile-jump').addEventListener('pointerup',()=>{jumpPointer=false;jumpHeld=false});

function platformAt(x,z){for(const p of pads)if(z<=p.start&&z>=p.end&&Math.abs(x)<4.94)return p;return null}
function update(dt,now){if(mode==='menu'||mode==='finish'){camera.position.set(0,eye,4);camera.rotation.set(0,0,0);return}if(mode==='pause')return;
 if(mode==='ready'){camera.position.set(0,eye,4);camera.rotation.set(0,0,0);return}
 elapsed=(now-startedAt)/1000;ui.timer.textContent=timeText(elapsed);
 let f=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-mobileMove.y;let s=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+mobileMove.x;const mag=Math.hypot(f,s);if(mag>1){f/=mag;s/=mag}
 const sy=Math.sin(player.yaw),cy=Math.cos(player.yaw);const wishX=-sy*f+cy*s,wishZ=-cy*f-sy*s;
 const grounded=player.grounded;const speed=Math.hypot(player.vx,player.vz);
 if(mag>.01){const accel=grounded?34:10;player.vx+=wishX*accel*dt;player.vz+=wishZ*accel*dt}
 if(grounded&&mag<.01){const drag=Math.max(0,1-7.5*dt);player.vx*=drag;player.vz*=drag}
 const maxSpeed=grounded?19:24;const current=Math.hypot(player.vx,player.vz);if(current>maxSpeed){player.vx*=maxSpeed/current;player.vz*=maxSpeed/current}
 if((jumpHeld||keys.Space||jumpPointer)&&grounded){player.vy=8.2;player.grounded=false;jumps++;airStart=now;}
 player.x+=player.vx*dt;player.z+=player.vz*dt;player.y+=player.vy*dt;player.vy-=22*dt;
 const under=platformAt(player.x,player.z);if(under&&player.vy<=0&&player.y<=under.top){if(!player.grounded){airTime+=Math.max(0,(now-airStart)/1000);player.y=under.top;player.vy=0;player.grounded=true;if(jumpHeld||keys.Space||jumpPointer){player.vy=8.2;player.grounded=false;jumps++;airStart=now}}else{player.y=under.top;player.vy=0}}else player.grounded=false;
 if(player.y < -15){ui.state.textContent='RESETTING YOUR LINE';resetPlayer();startedAt=now;return}
 if(player.z<finishZ){complete();return}
 const prog=clamp((4-player.z)/(4-finishZ),0,1),pct=Math.floor(prog*100);ui.progress.style.width=`${pct}%`;ui.pct.textContent=`${pct}%`;
 if(pct>=25&&prevProgress<25){ui.split.textContent=`25% — KEEP IT CLEAN`;ui.split.classList.add('show');setTimeout(()=>ui.split.classList.remove('show'),1350)}if(pct>=60&&prevProgress<60){ui.split.textContent=`60% — BEAUTIFUL LINE`;ui.split.classList.add('show');setTimeout(()=>ui.split.classList.remove('show'),1350)}prevProgress=pct;
 const kmh=Math.round(Math.hypot(player.vx,player.vz)*3.6);ui.speed.textContent=kmh;topSpeed=Math.max(topSpeed,Math.hypot(player.vx,player.vz));const lit=Math.min(speedBars.length,Math.floor(kmh/5));speedBars.forEach((b,i)=>b.classList.toggle('on',i<lit));
 ui.state.textContent=player.grounded?'FIND YOUR LINE':'AIRBORNE';
 const bob=player.grounded?Math.sin(now*.012)*Math.min(speed*.004,.035):0;camera.position.set(player.x,player.y+eye+bob,player.z);camera.rotation.set(player.pitch,player.yaw,0,'YXZ');camera.fov=76+Math.min(speed*.28,9);camera.updateProjectionMatrix();
}
function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.033);last=now;update(dt,now);renderer.render(scene,camera)}requestAnimationFrame(frame);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
// Allow touch look by swiping anywhere outside the movement pad.
let touchLook=null;renderer.domElement.addEventListener('touchstart',e=>{if(e.touches.length&&e.target!==stick){touchLook={x:e.touches[0].clientX,y:e.touches[0].clientY};if(mode==='ready')startRun()}},{passive:true});renderer.domElement.addEventListener('touchmove',e=>{if(!touchLook||!e.touches.length)return;const t=e.touches[0];player.yaw-=(t.clientX-touchLook.x)*.004;player.pitch=clamp(player.pitch-(t.clientY-touchLook.y)*.003,-1.2,1.2);touchLook={x:t.clientX,y:t.clientY}},{passive:true});renderer.domElement.addEventListener('touchend',()=>touchLook=null,{passive:true});

